// EdgeAdapterServiceServer is the server API for EdgeAdapterService service.
// All implementations must embed UnimplementedEdgeAdapterServiceServer
// for forward compatibility.
//
// EdgeAdapterService is the device-facing command API implemented by each Edge SDK.
// It intentionally uses shared command messages from common.proto so client-facing
// and device-facing SDKs do not drift into duplicate contracts.
// Each adapter also pushes scheduled ReportAssetRuntime requests to RemoteControlService.
type EdgeAdapterServiceServer interface {
	// Current self-describing command contract; also used to build runtime snapshots.
	GetCapabilities(context.Context, *proto.AssetCapabilitiesRequest) (*proto.AssetCapabilitiesResponse, error)
	// Flight Control
	TakeOff(context.Context, *proto.CoordinateCommandRequest) (*proto.CommandResponse, error)
	GoTo(context.Context, *proto.CoordinateCommandRequest) (*proto.CommandResponse, error)
	ReturnToHome(context.Context, *proto.ReturnToHomeCommandRequest) (*proto.CommandResponse, error)
	// Manual Control
	EnterManualControl(context.Context, *proto.ManualControlCommandRequest) (*proto.CommandResponse, error)
	ExitManualControl(context.Context, *proto.ManualControlCommandRequest) (*proto.CommandResponse, error)
	ManualControlInput(grpc.ClientStreamingServer[proto.ManualControlInputCommandRequest, proto.CommandResponse]) error
	// Gimbal, Camera & Detection
	LookAt(context.Context, *proto.LookAtCommandRequest) (*proto.CommandResponse, error)
	EnableGimbalTracking(context.Context, *proto.ToggleCommandRequest) (*proto.CommandResponse, error)
	GetDetections(*proto1.DetectionStreamRequest, grpc.ServerStreamingServer[proto1.DetectionBatch]) error
	PlayTTSAudio(context.Context, *proto.TextToSpeechCommandRequest) (*proto.CommandResponse, error)
	// Dock commands
	OpenCover(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	CloseCover(context.Context, *proto.CloseCoverCommandRequest) (*proto.CommandResponse, error)
	StartCharging(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	StopCharging(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	// Asset Management
	RebootAsset(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	BootSubAsset(context.Context, *proto.ToggleCommandRequest) (*proto.CommandResponse, error)
	RegisterAsset(context.Context, *proto.RegisterAssetCommandRequest) (*proto.CommandResponse, error)
	DeregisterAsset(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	// Debug & Maintenance
	SetRemoteDebugMode(context.Context, *proto.ToggleCommandRequest) (*proto.CommandResponse, error)
	ChangeAcMode(context.Context, *proto.ChangeAcModeCommandRequest) (*proto.CommandResponse, error)
	// Live Stream & Camera Capture
	StartLiveStream(context.Context, *proto.LiveStreamStartCommandRequest) (*proto.CommandResponse, error)
	StopLiveStream(context.Context, *proto.LiveStreamStopCommandRequest) (*proto.CommandResponse, error)
	ChangeLens(context.Context, *proto.ChangeCameraLensCommandRequest) (*proto.CommandResponse, error)
	ChangeZoom(context.Context, *proto.ChangeCameraZoomCommandRequest) (*proto.CommandResponse, error)
	CapturePhoto(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	StartRecording(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	StopRecording(context.Context, *proto.EmptyCommandRequest) (*proto.CommandResponse, error)
	LiveStreamSplitScreen(context.Context, *proto.ToggleCommandRequest) (*proto.CommandResponse, error)
	// Task Lifecycle
	PrepareTask(context.Context, *proto.TaskCommandRequest) (*proto.CommandResponse, error)
	StartTask(context.Context, *proto.TaskCommandRequest) (*proto.CommandResponse, error)
	StopTask(context.Context, *proto.TaskCommandRequest) (*proto.CommandResponse, error)
	PauseTask(context.Context, *proto.TaskCommandRequest) (*proto.CommandResponse, error)
	ResumeTask(context.Context, *proto.TaskCommandRequest) (*proto.CommandResponse, error)
	// Custom / Integrator-defined commands
	SendCustomCommand(context.Context, *proto.CustomCommandRequest) (*proto.CustomCommandResponse, error)
	mustEmbedUnimplementedEdgeAdapterServiceServer()
}

